Below is a **ready‑to‑use pattern** you can drop into any back‑end (Node, Python, Go, etc.) or front‑end code.  
It automatically:

1. **Detects the visitor’s IP address** (or you can pass it in explicitly).  
2. **Looks up the visitor’s country/city** via an IP‑geolocation service.  
3. **Maps that location to a greeting** in the most common language spoken there.  
4. **Falls back** to the browser’s `Accept‑Language` header (or a default “Hello”) if the location can’t be resolved.

---

## 1. High‑level flow diagram

```
+-------------------+        +----------------------+        +-------------------+
|  Client request   |  IP →  |  Geolocation service |  →  |  Greeting lookup  |
| (browser or API) |------->|  (e.g. MaxMind, ipapi) |------>|  (text / JSON)   |
+-------------------+        +----------------------+        +-------------------+
          |                                                    |
          |  (optional)                                        |
          |  Browser language header  ------------------------+
          v
   Response: "¡Hola!" / {"greeting":"Bonjour"} …
```

---

## 2. Minimal implementation (Node / Express)

```js
// ------------------------------------------------------------
// 1️⃣  Install the required packages
// ------------------------------------------------------------
// npm i express node-fetch
// (or yarn add express node-fetch)

const express = require('express');
const fetch = require('node-fetch');   // built‑in fetch in Node 18+ works too
const app = express();
const PORT = process.env.PORT || 3000;

// ------------------------------------------------------------
// 2️⃣  Helper: get a greeting from the language code
// ------------------------------------------------------------
const GREETINGS = {
  en: 'Hello',
  es: '¡Hola!',
  fr: 'Bonjour',
  de: 'Hallo',
  it: 'Ciao',
  pt: 'Olá',
  zh: '你好',
  ja: 'こんにちは',
  ko: '안녕하세요',
  ru: 'Привет',
  // add as many as you need …
};

function greetingFromLang(lang) {
  // `lang` may be "en-US", "es-ES", etc. → keep only the primary sub‑tag.
  const primary = lang.split('-')[0];
  return GREETINGS[primary] || GREETINGS['en'];
}

// ------------------------------------------------------------
// 3️⃣  Resolve IP → country → language (using a free IP API)
// ------------------------------------------------------------
async function getGreetingByIP(ip) {
  // Example free service: ipapi.co (no API key for low volume)
  const resp = await fetch(`https://ipapi.co/${ip}/json/`);
  if (!resp.ok) throw new Error('Geolocation lookup failed');
  const data = await resp.json();

  // `data.country_code` → ISO‑2 country (e.g. "ES")
  // `data.languages`   → comma‑separated list of language codes (e.g. "es,gl")
  const lang = data.languages?.split(',')[0] ?? 'en';
  return greetingFromLang(lang);
}

// ------------------------------------------------------------
// 4️⃣  Express route – returns greeting in the requested format
// ------------------------------------------------------------
app.get('/greet', async (req, res) => {
  try {
    // 4a. Determine the client IP.
    // Express puts the real IP in `req.ip` (or you may need X‑Forwarded‑For).
    const clientIP = req.headers['x-forwarded-for']?.split(',')[0]?.trim()
                  || req.socket?.remoteAddress;

    // 4b. Try the IP‑based greeting first.
    let greeting = await getGreetingByIP(clientIP);

    // 4c. If the IP service failed, fall back to the Accept‑Language header.
    if (!greeting) {
      const acceptLang = req.headers['accept-language']?.split(',')[0] ?? 'en';
      greeting = greetingFromLang(acceptLang);
    }

    // 4d. Optional: honour a `format=json` query‑string.
    if (req.query.format === 'json') {
      res.json({ greeting });
    } else {
      res.type('text/plain').send(greeting);
    }
  } catch (e) {
    // On any error, return a safe default.
    const fallback = greetingFromLang('en');
    if (req.query.format === 'json') {
      res.json({ greeting: fallback, error: e.message });
    } else {
      res.type('text/plain').send(fallback);
    }
  }
});

app.listen(PORT, () => console.log(`🌍 Greeting service listening on ${PORT}`));
```

### What the code does

| Step | Explanation |
|------|-------------|
| **IP detection** | Uses `X‑Forwarded‑For` (common behind proxies) or the raw socket address. |
| **Geolocation lookup** | Calls `https://ipapi.co/<IP>/json/` – returns country, city, and a list of languages. |
