const fetch = require('node-fetch');   // built‑in fetch in Node 18+ works too
const app = express();
const PORT = process.env.PORT || 3000;

// ------------------------------------------------------------
// 2️⃣  Helper: get a greeting from the language code
// ------------------------------------------------------------
