  en: 'Hello',
  es: '¡Hola!',
  fr: 'Bonjour',
  de: 'Hallo',
  it: 'Ciao',
  pt: 'Olá',
  zh: '你好',
  ja: 'こんにちは',
  ko: '안녕하세요',
  ru: 'Привет',
  // add as many as you need …
};

function greetingFromLang(lang) {
  // `lang` may be "en-US", "es-ES", etc. → keep only the primary sub‑tag.
  const primary = lang.split('-')[0];
